    sep_rows = [
        r for r, row in enumerate(grid)
        if sum(v == frame for v in row) >= w - 4
    ]
    if len(sep_rows) < 2:
        return [[0]]

    # Each distinct tick column is one output column.
    tick_cols = sorted({
        c
        for r in sep_rows
        for c, value in enumerate(grid[r])
        if value != frame
    })

    # Read the marker colors from each separator; absent marks take the
    # background color of the tiled interior immediately below.
    out = []
    for r in sep_rows[:-1]:
        row = []
        for c in tick_cols:
            value = grid[r][c]
            if value == frame:
                value = grid[min(r + 1, h - 1)][c]
            row.append(value)
        out.append(row)
    return out
